using System.Net;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests
{
    private sealed class StubHandler(HttpStatusCode status, string? body) : HttpMessageHandler
    {
        public HttpRequestMessage? Request { get; private set; }
        public string? RequestBody { get; private set; }

        protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken ct)
        {
            Request = request;
            RequestBody = request.Content is null ? null : await request.Content.ReadAsStringAsync(ct);
            var response = new HttpResponseMessage(status);
            if (body is not null) response.Content = new StringContent(body, Encoding.UTF8, "application/json");
            return response;
        }
    }

    private static (HttpPaymentGateway Gateway, StubHandler Handler) Create(HttpStatusCode status, string? body)
    {
        var handler = new StubHandler(status, body);
        var gateway = new HttpPaymentGateway(new HttpClient(handler) { BaseAddress = new Uri("https://provider.test") });
        return (gateway, handler);
    }

    [Fact]
    public async Task Sends_a_json_post_to_the_authorizations_endpoint_with_reference_amount_and_currency()
    {
        var (gateway, handler) = Create(HttpStatusCode.OK, """{"status":"approved"}""");

        await gateway.AuthorizeAsync("ORD-7", new Money(12.50m, "eur"), CancellationToken.None);

        Assert.Equal(HttpMethod.Post, handler.Request!.Method);
        Assert.Equal("https://provider.test/v1/authorizations", handler.Request.RequestUri!.ToString());
        Assert.Equal("application/json", handler.Request.Content!.Headers.ContentType!.MediaType);

        using var json = JsonDocument.Parse(handler.RequestBody!);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_status_is_read_as_approved()
    {
        var (gateway, _) = Create(HttpStatusCode.OK, """{"status":"approved"}""");

        Assert.Equal(AuthorizationOutcome.Approved, await gateway.AuthorizeAsync("A", new Money(1, "EUR"), CancellationToken.None));
    }

    [Fact]
    public async Task A_declined_status_is_read_as_declined()
    {
        var (gateway, _) = Create(HttpStatusCode.OK, """{"status":"declined"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await gateway.AuthorizeAsync("A", new Money(1, "EUR"), CancellationToken.None));
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        var (gateway, _) = Create(HttpStatusCode.OK, """{"id":"x1","status":"approved","risk":{"score":3}}""");

        Assert.Equal(AuthorizationOutcome.Approved, await gateway.AuthorizeAsync("A", new Money(1, "EUR"), CancellationToken.None));
    }

    [Theory]
    [InlineData("""{}""")]
    [InlineData("""{"status":null}""")]
    [InlineData("""{"status":"pending"}""")]
    [InlineData("""{"status":"APPROVED"}""")]
    [InlineData("null")]
    public async Task Anything_other_than_an_approved_status_is_never_treated_as_approved(string body)
    {
        var (gateway, _) = Create(HttpStatusCode.OK, body);

        Assert.Equal(AuthorizationOutcome.Declined, await gateway.AuthorizeAsync("A", new Money(1, "EUR"), CancellationToken.None));
    }

    [Fact]
    public async Task A_402_refusal_is_a_decline_even_with_an_unreadable_body()
    {
        var (gateway, _) = Create(HttpStatusCode.PaymentRequired, "not json");

        Assert.Equal(AuthorizationOutcome.Declined, await gateway.AuthorizeAsync("A", new Money(1, "EUR"), CancellationToken.None));
    }

    [Fact]
    public async Task A_402_with_an_approved_looking_body_is_still_a_decline()
    {
        var (gateway, _) = Create(HttpStatusCode.PaymentRequired, """{"status":"approved"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await gateway.AuthorizeAsync("A", new Money(1, "EUR"), CancellationToken.None));
    }

    [Theory]
    [InlineData(HttpStatusCode.BadRequest)]
    [InlineData(HttpStatusCode.Unauthorized)]
    [InlineData(HttpStatusCode.UnprocessableEntity)]
    [InlineData(HttpStatusCode.InternalServerError)]
    [InlineData(HttpStatusCode.ServiceUnavailable)]
    public async Task Other_error_statuses_surface_as_failures_not_declines(HttpStatusCode status)
    {
        var (gateway, _) = Create(status, """{"status":"approved"}""");

        await Assert.ThrowsAsync<HttpRequestException>(() => gateway.AuthorizeAsync("A", new Money(1, "EUR"), CancellationToken.None));
    }

    [Fact]
    public async Task A_success_with_a_malformed_body_surfaces_as_a_failure()
    {
        var (gateway, _) = Create(HttpStatusCode.OK, "<html>oops</html>");

        await Assert.ThrowsAsync<JsonException>(() => gateway.AuthorizeAsync("A", new Money(1, "EUR"), CancellationToken.None));
    }

    [Fact]
    public async Task A_success_with_a_wrongly_typed_status_surfaces_as_a_failure()
    {
        var (gateway, _) = Create(HttpStatusCode.OK, """{"status":{"value":"approved"}}""");

        await Assert.ThrowsAsync<JsonException>(() => gateway.AuthorizeAsync("A", new Money(1, "EUR"), CancellationToken.None));
    }
}
